<script setup>
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { api, errorMessage, imageUrl, unwrap } from '../api'
const props = defineProps({ section: String })
const page = computed(() => props.section || 'products')
const items = ref([]), cart = ref({ items: [], total_amount: 0 }), orders = ref([]), selected = ref(null), productDetail = ref(null), error = ref(''), message = ref(''), species = ref(''), category = ref(''), query = ref(''), pageIndex = ref(1), pages = ref(1), quantity = ref(1)
const address = reactive({ recipient_name: '', recipient_phone: '', address_province: '', address_city: '', address_district: '', address_detail: '', note: '' })
async function load() { error.value = ''; try { if (page.value === 'products') { const data = (await api.get('/shop/products', { params: { page: pageIndex.value, species: species.value || undefined, category: category.value || undefined, q: query.value || undefined } })).data; items.value = data.items || []; pages.value = data.pages || 1 } else if (page.value === 'cart') cart.value = (await api.get('/shop/cart')).data; else if (page.value === 'orders') { const data = (await api.get('/shop/orders', { params: { page: pageIndex.value } })).data; orders.value = data.items || []; pages.value = data.pages || 1 } } catch (e) { error.value = errorMessage(e) } }
onMounted(load); watch(page, load)
function filter() { pageIndex.value = 1; load() }
function changePage(next) { pageIndex.value = next; load() }
async function viewProduct(product) { try { productDetail.value = (await api.get(`/shop/products/${product.id}`)).data.product } catch (e) { error.value = errorMessage(e) } }
async function add(product) { try { unwrap(await api.post('/shop/cart', { product_id: product.id, quantity: Number(quantity.value) })); message.value = `${product.name} 已加入购物车` } catch (e) { error.value = errorMessage(e) } }
async function remove(item) { try { unwrap(await api.delete(`/shop/cart/${item.id}`)); await load() } catch (e) { error.value = errorMessage(e) } }
async function clear() { if (!confirm('确定清空购物车吗？')) return; try { unwrap(await api.post('/shop/cart/clear')); await load() } catch (e) { error.value = errorMessage(e) } }
async function checkout() { try { unwrap(await api.post('/shop/orders', address)); message.value = '下单成功，可在我的订单中查看进度。'; await load() } catch (e) { error.value = errorMessage(e) } }
async function detail(order) { try { selected.value = (await api.get(`/shop/orders/${order.id}`)).data.order } catch (e) { error.value = errorMessage(e) } }
async function cancel(order) { if (!confirm('确定取消此订单吗？')) return; try { unwrap(await api.put(`/shop/orders/${order.id}/status`, { status: 'cancelled' })); await load() } catch (e) { error.value = errorMessage(e) } }
</script>
<template>
  <div class="page-head"><div><h1>{{ page === 'cart' ? '购物车' : page === 'orders' ? '我的订单' : '宠物商城' }}</h1><p>挑选适合毛孩子的用品，让照护更轻松</p></div></div>
  <div class="tabs"><RouterLink to="/shop/products">商品浏览</RouterLink><RouterLink to="/shop/cart">购物车</RouterLink><RouterLink to="/shop/orders">我的订单</RouterLink></div>
  <div v-if="error" class="message error">{{ error }}</div><div v-if="message" class="message">{{ message }}</div>
  <template v-if="page === 'products'"><form class="card inline-form" style="margin-bottom:20px" @submit.prevent="filter"><label class="field"><span>搜索商品</span><input v-model.trim="query" placeholder="商品名称"></label><label class="field"><span>适用宠物</span><select v-model="species" @change="filter"><option value="">全部</option><option value="dog">狗狗</option><option value="cat">猫咪</option></select></label><label class="field"><span>商品分类</span><select v-model="category" @change="filter"><option value="">全部</option><option value="food">宠物食品</option><option value="toy">宠物玩具</option><option value="accessory">用品配件</option><option value="medicine">健康护理</option><option value="other">其他</option></select></label><button class="btn">搜索</button></form><div v-if="items.length" class="grid"><div v-for="product in items" :key="product.id" class="card"><img v-if="product.image" class="product-image" :src="imageUrl(product.image)" :alt="product.name"><div v-else class="pet-placeholder">🛍️</div><h3 style="margin-top:15px">{{ product.name }}</h3><p class="muted small">{{ product.category_display }} · {{ product.target_species_display }}</p><p class="small">{{ product.description }}</p><strong style="color:#d07743;font-size:22px">¥{{ Number(product.price).toFixed(2) }}</strong><p class="muted small">库存 {{ product.stock }}</p><div class="actions"><button class="btn secondary" @click="viewProduct(product)">查看详情</button><input v-model.number="quantity" aria-label="购买数量" class="search-input number-input" type="number" min="1" :max="product.stock"><button class="btn" :disabled="product.stock < 1" @click="add(product)">加入购物车</button></div></div></div><div v-else class="empty">没有符合条件的商品。</div></template>
  <template v-else-if="page === 'cart'"><div v-if="cart.items?.length" class="two-col"><div class="card"><div v-for="item in cart.items" :key="item.id" class="list-row"><div><strong>{{ item.product?.name || '商品' }}</strong><div class="muted small">¥{{ item.product?.price }} × {{ item.quantity }}</div></div><button class="btn danger" @click="remove(item)">移除</button></div><div class="list-row"><strong>合计 ¥{{ Number(cart.total_amount).toFixed(2) }}</strong><button class="btn secondary" @click="clear">清空购物车</button></div></div><form class="card" @submit.prevent="checkout"><h3>收货信息</h3><div class="form-grid"><label class="field"><span>收件人</span><input v-model="address.recipient_name" required></label><label class="field"><span>联系电话</span><input v-model="address.recipient_phone" required type="tel"></label><label class="field"><span>省份</span><input v-model="address.address_province" required></label><label class="field"><span>城市</span><input v-model="address.address_city" required></label><label class="field"><span>区县</span><input v-model="address.address_district"></label><label class="field full"><span>详细地址</span><input v-model="address.address_detail" required></label><label class="field full"><span>订单备注</span><textarea v-model="address.note"></textarea></label></div><button class="btn" style="margin-top:15px">确认下单</button></form></div><div v-else class="empty">购物车还是空的，去<RouterLink to="/shop/products">挑选商品</RouterLink>吧。</div></template>
  <template v-else><div v-if="orders.length" class="card"><div v-for="order in orders" :key="order.id" class="list-row"><div><strong>订单 #{{ order.id }}</strong><div class="muted small">{{ order.created_at?.slice(0,16) }} · {{ order.item_count }} 件商品 · ¥{{ Number(order.total_amount).toFixed(2) }}</div></div><div class="actions"><span class="tag">{{ order.status_display }}</span><button class="btn secondary" @click="detail(order)">查看详情</button><button v-if="order.status === 'pending'" class="btn danger" @click="cancel(order)">取消订单</button></div></div></div><div v-else class="empty">还没有订单，<RouterLink to="/shop/products">开始选购</RouterLink>。</div></template>
  <div v-if="pages > 1 && page !== 'cart'" class="actions" style="justify-content:center"><button class="btn secondary" :disabled="pageIndex<=1" @click="changePage(pageIndex-1)">上一页</button><span class="muted small" style="align-self:center">第 {{ pageIndex }} / {{ pages }} 页</span><button class="btn secondary" :disabled="pageIndex>=pages" @click="changePage(pageIndex+1)">下一页</button></div>
  <div v-if="productDetail" class="modal-backdrop" @click.self="productDetail=null"><div class="modal"><div class="page-head"><h2>{{ productDetail.name }}</h2><button class="text-button" @click="productDetail=null">关闭 ✕</button></div><img v-if="productDetail.image" :src="imageUrl(productDetail.image)" :alt="productDetail.name" class="product-image" style="height:220px"><p>{{ productDetail.description }}</p><p class="muted small">{{ productDetail.category_display }} · {{ productDetail.target_species_display }} · 库存 {{ productDetail.stock }}</p><strong style="color:#d07743;font-size:24px">¥{{ productDetail.price }}</strong><div class="actions"><button class="btn" :disabled="productDetail.stock<1" @click="add(productDetail);productDetail=null">加入购物车</button></div></div></div>
  <div v-if="selected" class="modal-backdrop" @click.self="selected=null"><div class="modal"><div class="page-head"><h2>订单 #{{ selected.id }}</h2><button class="text-button" @click="selected=null">关闭 ✕</button></div><p>状态：{{ selected.status_display }} · 合计：¥{{ selected.total_amount }}</p><p>收件人：{{ selected.recipient_name }} {{ selected.recipient_phone }}</p><p>地址：{{ selected.address_full }}</p><div v-for="item in selected.items" :key="item.id" class="list-row"><span>{{ item.product_name }} × {{ item.quantity }}</span><strong>¥{{ item.subtotal }}</strong></div></div></div>
</template>
